from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GEMVER kernel.
# - First, copy z into x so x will accumulate beta * A^T * y on top of z.
# - Then fuse the matrix rank-1 update on A with the GEMV computing x.
#   This gives a single row-major pass over A for both operations.
# - Finally, perform w += alpha * A * x; this is a standard GEMV.

@proc
def kernel_gemver(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # Initialize x with z. After this, x[j] will hold:
    #   x[j] = z[j] + beta * sum_i A[i, j] * y[i]
    # built up in the fused loop below.
    for j_init in seq(0, n):
        x[j_init] = z[j_init]

    # Fused matrix update and GEMV:
    #   A[i, j] = A[i, j] + u1[i] * v1[j] + u2[i] * v2[j]
    #   x[j]    = x[j] + beta * A[i, j] * y[i]
    # We traverse rows of A to improve spatial locality.
    for i_fused in seq(0, n):
        u1_i: DATA_TYPE
        u2_i: DATA_TYPE
        beta_y_i: DATA_TYPE

        u1_i = u1[i_fused]
        u2_i = u2[i_fused]
        beta_y_i = beta * y[i_fused]

        for j_fused in seq(0, n):
            a_ij: DATA_TYPE
            a_ij = A[i_fused, j_fused] + u1_i * v1[j_fused] + u2_i * v2[j_fused]
            A[i_fused, j_fused] = a_ij
            x[j_fused] = x[j_fused] + a_ij * beta_y_i

    # Final GEMV: w[i] += alpha * sum_j A[i, j] * x[j]
    # This pass also traverses A row-major.
    for i_w in seq(0, n):
        for j_w in seq(0, n):
            w[i_w] = w[i_w] + alpha * A[i_w, j_w] * x[j_w]


# Scheduling: improve locality in the final GEMV and expose parallelism.
# We tile the inner j_w loop and parallelize the outer i_w loop.
TILE_J = 64

kernel_gemver_scheduled = kernel_gemver

# Tile the j_w loop to operate on contiguous blocks of A's rows and x.
j_w_loop = kernel_gemver_scheduled.find_loop("j_w")
kernel_gemver_scheduled = divide_loop(
    kernel_gemver_scheduled,
    j_w_loop,
    TILE_J,
    ("j_outer", "j_inner"),
    tail="guard",
)

# Parallelize over rows of w (i_w loop); each row is independent.
i_w_loop = kernel_gemver_scheduled.find_loop("i_w")
kernel_gemver_scheduled = parallelize_loop(kernel_gemver_scheduled, i_w_loop)

# Expose the scheduled kernel under the original name expected by the C driver.
kernel_gemver = rename(kernel_gemver_scheduled, "kernel_gemver")
